"""Golden parity with the TypeScript implementations (generated by parity/generate_golden.ts)."""
import json
from pathlib import Path

import pytest

from pyr_matching import hybrid_v01
from pyr_matching.optimizer import solve_assignments

PARITY = Path(__file__).resolve().parents[1] / "parity"


def _load(name):
    return json.loads((PARITY / name).read_text(encoding="utf-8"))["cases"]


@pytest.mark.parametrize("case", _load("golden_hybrid_v01.json"), ids=lambda c: c["student"]["id"])
def test_hybrid_v01_matches_typescript_exactly(case):
    actual = hybrid_v01.calculate_pair(case["student"], case["position"], case["config"], case["semantic"])
    assert actual == case["expected"]


@pytest.mark.parametrize("idx_case", list(enumerate(_load("golden_p6c.json"))), ids=lambda c: f"solver{c[0]}")
def test_p6c_solver_matches_typescript_exactly(idx_case):
    _, case = idx_case
    assert solve_assignments(case["input"], case["excluded"]) == case["expected"]


def test_golden_files_are_synthetic_only():
    text = (PARITY / "golden_hybrid_v01.json").read_text(encoding="utf-8") + (PARITY / "golden_p6c.json").read_text(encoding="utf-8")
    assert "@" not in text  # no e-mail addresses
